'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const te=new TextEncoder(),td=new TextDecoder(),sleep=ms=>new Promise(r=>setTimeout(r,ms));
const b64=u=>{let s='';for(let i=0;i<u.length;i+=8192)s+=String.fromCharCode.apply(null,u.subarray(i,i+8192));return btoa(s)};
const ub64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const VER='v2.2';let mraw,db,key,view='home',P=[],page=0,F={},tm,IM=null;
const COLS=[['id','Patient ID'],['name','Full name'],['dob','Date of birth'],['gender','Gender'],['phone','Mobile'],['address','Address'],['village','Village/City'],['district','District'],['state','State'],['blood','Blood group'],['caste','Caste / category'],['allergies','Allergies'],['history','Medical history'],['diseases','Diagnosis'],['meds','Medications'],['notes','Notes'],['emergency','Emergency contact'],['family','Family ID'],['relation','Relation'],['reg','Registration date']];
const open=()=>new Promise((res,rej)=>{const r=indexedDB.open('mcpm',1);r.onupgradeneeded=()=>{const d=r.result,p=d.createObjectStore('patients',{keyPath:'id'});['name','phone','family','deleted'].forEach(i=>p.createIndex(i,i));d.createObjectStore('audit',{autoIncrement:true});d.createObjectStore('meta')};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});
const st=(s,m)=>db.transaction(s,m).objectStore(s),R=r=>new Promise((a,b)=>{r.onsuccess=()=>a(r.result);r.onerror=()=>b(r.error)});
const mget=k=>R(st('meta').get(k)),mset=(k,v)=>R(st('meta','readwrite').put(v,k));
const load=async()=>{P=await R(st('patients').getAll())},log=(a,d)=>R(st('audit','readwrite').add({t:Date.now(),a,d})),A=()=>P.filter(p=>!p.deleted);
const today=()=>new Date().toISOString().slice(0,10);
function toast(m,e){const t=$('#toast');t.textContent=m;t.className='show'+(e?' err':'');clearTimeout(t._t);t._t=setTimeout(()=>t.className='',3500)}
function modal(h){$('#modal').innerHTML=`<div class="card dlg" role="dialog" aria-modal="true">${h}</div>`;$('#modal').hidden=false}
function closeM(){$('#modal').hidden=true;$('#modal').innerHTML=''}
function ask(l,pw=true){return new Promise(res=>{modal(`<label>${esc(l)}<input id="ask" type="${pw?'password':'text'}" autocomplete="off"></label><div class="row"><button class="btn ghost" id="ac">Cancel</button><button class="btn" id="ao">OK</button></div>`);$('#ask').focus();$('#ac').onclick=()=>{closeM();res(null)};$('#ao').onclick=()=>{const v=$('#ask').value;closeM();res(v)}})}
/* crypto */
async function derive(pw,salt){const m=await crypto.subtle.importKey('raw',te.encode(pw),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function seal(k,t){const iv=crypto.getRandomValues(new Uint8Array(12));return{iv:b64(iv),d:b64(new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,te.encode(t))))}}
const unseal=async(k,o)=>td.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:ub64(o.iv)},k,ub64(o.d)));
async function verifyPin(pw){try{const a=await mget('auth');await openM(a.wrap,pw,ub64(a.salt));return true}catch{return false}}
/* auth */
async function boot(){{const b=document.createElement('button');b.id='lgb';b.textContent='मराठी/EN';b.setAttribute('aria-label','Language');b.onclick=setLg;b.style.cssText='position:fixed;top:8px;right:8px;z-index:30;padding:5px 10px;border-radius:8px;border:1px solid #fff;background:#0b2545;color:#fff;font-size:13px';document.body.appendChild(b)}if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});document.documentElement.dataset.t=localStorage.t||'';try{db=await open();await load()}catch(e){document.body.innerHTML='<p style="padding:20px">Database could not be opened: '+esc(e.message)+'</p>';return}lockUI(!await mget('auth'))}
function lockUI(setup){$('#app').hidden=true;$('#lock').hidden=false;$('#lock').innerHTML=`<div class="card"><h2>🩺 MediCare Patient Manager</h2><p class="mut">${setup?'Create a PIN or password (min. 6 characters). There is no reset or backdoor — keep it safe.':'Enter your PIN or password.'}</p><input id="pin" type="password" placeholder="PIN / password" autocomplete="off">${setup?'<input id="pin2" type="password" placeholder="Confirm">':''}<p class="mut"><small>Works offline. Install on Android: Chrome menu ⋮ → Install app.</small></p><p id="lerr" style="color:#c0392b"></p><button class="btn" onclick="unlock(${setup})">${setup?'Create':'Unlock'}</button>${setup?'':'<button class="btn ghost" style="width:100%;margin:10px 0 0" onclick="forgot()">Forgot PIN / password?</button>'}<p class="mut"><small>MediCare Patient Manager ${VER}</small></p></div>`;$('#pin').focus()}
const rnd=n=>crypto.getRandomValues(new Uint8Array(n)),rawKey=r=>crypto.subtle.importKey('raw',r,'AES-GCM',false,['encrypt','decrypt']);
const wrapM=async(raw,pw,salt)=>seal(await derive(pw,salt),b64(raw)),openM=async(w,pw,salt)=>ub64(await unseal(await derive(pw,salt),w));
const RCA='ABCDEFGHJKLMNPQRSTUVWXYZ23456789',newRC=()=>[...rnd(20)].map(x=>RCA[x%32]).join('').match(/.{4}/g).join('-'),normRC=s=>s.toUpperCase().replace(/[^A-Z0-9]/g,'');
async function enter(raw){mraw=raw;key=await rawKey(raw);$('#lock').hidden=true;$('#app').hidden=false;go(view);arm()}
let curRC='';
async function showRC(rc){curRC=rc;const ph=(await mget('rcPhone'))||'';modal(`<h3>Save your recovery code</h3><p style="font-size:20px;letter-spacing:1px;word-break:break-all"><b>${rc}</b></p><p class="mut"><small>Write this on paper and keep it safe. If you forget your PIN, this code lets you set a new one without losing data. It is shown only once.</small></p><label>Mobile number for the SMS<input id="rcph" type="tel" inputmode="numeric" placeholder="10-digit mobile number" value="${esc(ph)}"></label><button class="btn ghost" style="width:100%" onclick="sendRC()">Send code by SMS</button><p class="mut"><small>This opens your phone's messages app with the code filled in; you must tap Send there. SMS is not private: anyone who can read that phone's messages and use this phone could reset the PIN. Use your own number and delete the message if unsure.</small></p><div class="row"><button class="btn ghost" onclick="navigator.clipboard&&navigator.clipboard.writeText(curRC);toast('Copied')">Copy</button><button class="btn" onclick="curRC='';closeM()">I have saved it</button></div>`)}
async function sendRC(){const n=normPh($('#rcph').value);if(!/^[6-9]\d{9}$/.test(n))return toast('Enter a valid 10-digit mobile number',1);try{await mset('rcPhone',n);await log('recovery-code','SMS app opened for sending');const a=document.createElement('a');a.href='sms:+91'+n+'?body='+encodeURIComponent('MediCare Patient Manager recovery code: '+curRC+'\nKeep this safe. Do not share it.');a.click();toast('Messages app opened. Tap Send there. Nothing is sent until you do.')}catch(x){toast('Failed: '+x.message,1)}}
async function unlock(setup){const p=$('#pin').value,e=$('#lerr');if(p.length<6)return e.textContent='Use at least 6 characters.';e.textContent='Please wait…';
try{if(setup){if(p!==$('#pin2').value)return e.textContent='Entries do not match.';const raw=rnd(32),salt=rnd(16),rs=rnd(16),rc=newRC();await mset('auth',{v:2,salt:b64(salt),wrap:await wrapM(raw,p,salt),rsalt:b64(rs),rwrap:await wrapM(raw,normRC(rc),rs)});await log('setup','PIN created');await enter(raw);showRC(rc)}
else{const a=await mget('auth');if(a.v===2){let raw;try{raw=await openM(a.wrap,p,ub64(a.salt))}catch{return e.textContent='Incorrect PIN.'}await enter(raw)}
else{let old;try{old=await derive(p,ub64(a.salt));if(await unseal(old,a.chk)!=='ok')throw 0}catch{return e.textContent='Incorrect PIN.'}
const raw=rnd(32),nk=await rawKey(raw),salt=rnd(16),rs=rnd(16),rc=newRC(),ps=[];for(const x of P){const q={...x};if(q.aad)q.aad=await seal(nk,await unseal(old,q.aad));if(q.abh)q.abh=await seal(nk,await unseal(old,q.abh));ps.push(q)}
const au={v:2,salt:b64(salt),wrap:await wrapM(raw,p,salt),rsalt:b64(rs),rwrap:await wrapM(raw,normRC(rc),rs)},t=db.transaction(['patients','meta'],'readwrite');ps.forEach(q=>t.objectStore('patients').put(q));t.objectStore('meta').put(au,'auth');await new Promise((x,y)=>{t.oncomplete=x;t.onerror=()=>y(t.error)});await load();await enter(raw);showRC(rc)}}}catch(x){e.textContent='Error: '+x.message}}
async function chgPin(){const c=await ask('Current PIN / password');if(c==null)return;if(!await verifyPin(c))return toast('Incorrect PIN',1);const n1=await ask('New PIN / password (min. 6 characters)');if(n1==null)return;if(n1.length<6)return toast('Use at least 6 characters',1);const n2=await ask('Confirm new PIN / password');if(n1!==n2)return toast('Entries do not match',1);try{const a=await mget('auth'),s=rnd(16);a.salt=b64(s);a.wrap=await wrapM(mraw,n1,s);await mset('auth',a);await log('pin-change','');toast('PIN changed. Use the new PIN next time.')}catch(x){toast('Failed: '+x.message,1)}}
async function newRecovery(){const c=await ask('Enter your PIN to create a new recovery code');if(c==null)return;if(!await verifyPin(c))return toast('Incorrect PIN',1);try{const a=await mget('auth'),rs=rnd(16),rc=newRC();a.rsalt=b64(rs);a.rwrap=await wrapM(mraw,normRC(rc),rs);await mset('auth',a);await log('recovery-code','renewed');showRC(rc)}catch(x){toast('Failed: '+x.message,1)}}
function forgot(){modal(`<h3>Forgot PIN</h3><p class="mut"><small>Enter the recovery code you saved when you created the PIN, then choose a new PIN. Your patient data stays intact.</small></p><label>Recovery code<input id="rc" autocomplete="off" placeholder="XXXX-XXXX-XXXX-XXXX-XXXX"></label><label>New PIN / password<input id="np1" type="password"></label><label>Confirm<input id="np2" type="password"></label><div class="row"><button class="btn ghost" onclick="closeM()">Cancel</button><button class="btn" onclick="doForgot()">Reset PIN</button></div><hr><p class="mut"><small>No recovery code? Then the data cannot be opened. You can erase this phone's data and restore from an encrypted backup file.</small></p><button class="btn red" onclick="eraseAll()">Erase all data on this phone</button>`)}
async function doForgot(){const n1=$('#np1').value;if(n1.length<6||n1!==$('#np2').value)return toast('New PIN: at least 6 characters, both entries must match',1);try{const a=await mget('auth');if(a.v!==2)throw 0;let raw;try{raw=await openM(a.rwrap,normRC($('#rc').value),ub64(a.rsalt))}catch{return toast('Wrong recovery code',1)}const s=rnd(16);a.salt=b64(s);a.wrap=await wrapM(raw,n1,s);await mset('auth',a);await log('pin-reset','via recovery code');closeM();await enter(raw);toast('PIN reset')}catch{toast('Recovery is not available for this installation',1)}}
async function eraseAll(){const t=await ask('Type ERASE to permanently delete ALL patient data on this phone',false);if(t!=='ERASE')return toast('Cancelled');try{const tx=db.transaction(['patients','audit','meta'],'readwrite');['patients','audit','meta'].forEach(n=>tx.objectStore(n).clear());await new Promise((x,y)=>{tx.oncomplete=x;tx.onerror=()=>y(tx.error)});P=[];F={};closeM();lockUI(true);toast('All data erased. Create a new PIN, then restore a backup if you have one.')}catch(x){toast('Failed: '+x.message,1)}}
function lock(){key=null;mraw=null;closeM();lockUI(false)}
function arm(){clearTimeout(tm);if(key)tm=setTimeout(lock,12e4)}['click','keydown','touchstart'].forEach(e=>addEventListener(e,arm));
/* helpers */
function age(d){if(!d)return null;const b=new Date(d),n=new Date();let y=n.getFullYear()-b.getFullYear();if(n<new Date(n.getFullYear(),b.getMonth(),b.getDate()))y--;return y}
function validDate(s){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return false;const d=new Date(s);return !isNaN(d)&&d.toISOString().slice(0,10)===s&&d<=new Date()}
const normDate=s=>{s=(s||'').trim();const m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:s};
const normPh=s=>(s||'').replace(/[\s-]/g,'').replace(/^(\+91|91)(?=\d{10}$)/,'');
const nextId=async()=>{const n=((await mget('seq'))||0)+1;await mset('seq',n);return'P'+String(n).padStart(6,'0')};
function go(v){if(v==='list'&&view!=='list')F={};view=v;page=0;document.querySelectorAll('nav [data-v]').forEach(b=>b.className=b.dataset.v===v?'on':'');({home,list,imp,more})[v]();$('#main').scrollTo?.(0,0)}
document.addEventListener('click',e=>{const b=e.target.closest('nav [data-v]');if(b)go(b.dataset.v)});
/* dashboard */
function bars(o){const e=Object.entries(o).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]).slice(0,8),mx=Math.max(1,...e.map(x=>x[1]));return e.length?e.map(([k,v])=>`<div class="bar"><span>${esc(k)}</span><i style="width:${Math.max(4,v/mx*60)}%"></i><b>${v}</b></div>`).join(''):'<p class="mut">No data yet.</p>'}
function home(){const a=A(),g={Male:0,Female:0,Other:0,'Not specified':0},ag={'0–12':0,'13–17':0,'18–39':0,'40–59':0,'60+':0},d={};
a.forEach(p=>{g[['Male','Female','Other'].includes(p.gender)?p.gender:'Not specified']++;const y=age(p.dob);if(y!=null)ag[y<13?'0–12':y<18?'13–17':y<40?'18–39':y<60?'40–59':'60+']++;(p.diseases||[]).forEach(x=>{const k=x.toLowerCase();d[k]=(d[k]||0)+1})});
const rec=[...a].sort((x,y)=>y.updated-x.updated).slice(0,5);
$('#main').innerHTML=`<div class="grid"><div class="card stat"><small>Total patients</small><br><b>${a.length}</b></div>${Object.entries(g).map(([k,v])=>`<div class="card stat"><small>${k}</small><br><b>${v}</b></div>`).join('')}</div>
<div class="card"><div class="row"><button class="btn" onclick="pform()">Add patient</button><button class="btn" onclick="go('list')">Search</button><button class="btn" onclick="go('imp')">Import</button><button class="btn" onclick="go('more')">Reports &amp; backup</button></div></div>
<div class="card"><h3>Age groups</h3>${bars(ag)}</div><div class="card"><h3>Common conditions</h3>${bars(d)}</div>
<div class="card"><h3>Recently updated</h3>${rec.map(row).join('')||'<p class="mut">No records yet. Add a patient or use demo data in More.</p>'}</div>`}
/* list */
function match(p){const y=age(p.dob),q=(F.q||'').toLowerCase().trim();
if(q&&![p.id,p.name,p.phone,p.family,p.village,...(p.diseases||[])].join(' ').toLowerCase().includes(q))return false;
if(F.g&&p.gender!==F.g)return false;if(F.a1&&(y==null||y<+F.a1))return false;if(F.a2&&(y==null||y>+F.a2))return false;
if(F.d){const ds=F.d.toLowerCase().split(/[,;]/).map(s=>s.trim()).filter(Boolean),pd=(p.diseases||[]).map(s=>s.toLowerCase());if(ds.length&&!ds[F.dm==='any'?'some':'every'](x=>pd.some(z=>z.includes(x))))return false}
if(F.dob1&&(!p.dob||p.dob<F.dob1))return false;if(F.dob2&&(!p.dob||p.dob>F.dob2))return false;
if(F.v&&!(p.village||'').toLowerCase().includes(F.v.toLowerCase()))return false;if(F.b&&p.blood!==F.b)return false;if(F.c&&!(p.caste||'').toLowerCase().includes(F.c.toLowerCase()))return false;if(F.f&&p.family!==F.f)return false;
if(F.r1&&(p.reg||'')<F.r1)return false;if(F.r2&&(p.reg||'')>F.r2)return false;if(F.m&&(!p.dob||+p.dob.slice(5,7)!==+F.m))return false;
if(F.inc&&p.name&&p.dob&&p.phone&&p.gender&&(p.diseases||[]).length)return false;return F.arch?!!p.deleted:!p.deleted}
const inp=(k,l,t='text')=>`<div><label>${l}<input type="${t}" value="${esc(F[k]||'')}" oninput="F.${k}=this.value;page=0;draw()"></label></div>`;
const row=p=>`<div class="card item" onclick="profile('${p.id}')"><b>${esc(p.name)}</b> <small>${p.id}${p.family?' · '+esc(p.family):''}</small><br><small>${age(p.dob)??'?'} yrs · ${esc(p.gender||'—')} · ${esc(p.phone||'no phone')} ${(p.diseases||[]).length?'· '+esc(p.diseases.join(', ')):''}</small>${p.deleted?`<br><button class="btn" onclick="event.stopPropagation();setDel('${p.id}',false)">Restore</button>`:''}</div>`;
function list(){const sf=JSON.parse(localStorage.sf||'{}'),na=P.filter(p=>p.deleted).length;$('#main').innerHTML=`<div class="card"><div class="row"><button class="btn ghost" onclick="qf(0,12)">Children 0–12</button><button class="btn ghost" onclick="qf(18,59)">Adults 18–59</button><button class="btn ghost" onclick="qf(60,'')">Seniors 60+</button><button class="btn ${F.arch?'':'ghost'}" onclick="F.arch=!F.arch;page=0;list()"><span>Archived records</span> <small>(${na})</small></button></div><input placeholder="Search ID, name, phone, disease, family, village…" value="${esc(F.q||'')}" oninput="F.q=this.value;page=0;draw()" aria-label="Search">
<details ${nF()?'open':''}><summary>Filters</summary><div class="grid">${inp('a1','Age from','number')}${inp('a2','Age to','number')}${inp('d','Diseases (comma = all)')}<div><label>Disease match<select onchange="F.dm=this.value;page=0;draw()"><option value="all" ${F.dm!=='any'?'selected':''}>All of them</option><option value="any" ${F.dm==='any'?'selected':''}>Any one</option></select></label></div>${inp('dob1','Born from','date')}${inp('dob2','Born to','date')}${inp('v','Village/city')}${inp('f','Family ID')}${inp('c','Caste / category')}${inp('r1','Registered from','date')}${inp('r2','Registered to','date')}
<div><label>Gender<select onchange="F.g=this.value;page=0;draw()">${['','Male','Female','Other','Prefer not to say'].map(x=>`<option ${F.g===x?'selected':''}>${x}</option>`).join('')}</select></label></div>
<div><label>Blood group<select onchange="F.b=this.value;page=0;draw()">${['','A+','A-','B+','B-','AB+','AB-','O+','O-'].map(x=>`<option ${F.b===x?'selected':''}>${x}</option>`).join('')}</select></label></div>
<div><label>Birthday month<select onchange="F.m=this.value;page=0;draw()"><option value="">Any</option>${[...Array(12)].map((_,i)=>`<option value="${i+1}" ${F.m==i+1?'selected':''}>${i+1}</option>`).join('')}</select></label></div></div>
<label><input type="checkbox" style="width:auto" ${F.inc?'checked':''} onchange="F.inc=this.checked;draw()"> Incomplete records only</label> <label><input type="checkbox" style="width:auto" ${F.arch?'checked':''} onchange="F.arch=this.checked;draw()"> Archived</label>
<div class="row"><button class="btn ghost" onclick="F={};list()">Reset</button><button class="btn ghost" onclick="saveF()">Save filter</button>${Object.keys(sf).map(k=>`<button class="btn ghost" onclick="F=JSON.parse(localStorage.sf)['${esc(k)}'];list()">${esc(k)}</button>`).join('')}</div></details></div><div id="res"></div>`;draw()}
const nF=()=>Object.keys(F).filter(k=>k!=='q'&&k!=='arch'&&F[k]).length;
const qf=(a,b)=>{F.a1=a;F.a2=b;page=0;list()};
function openArchive(){go('list');F={arch:true};list()}
const hits=()=>A.call?P.filter(match).sort((a,b)=>a.name.localeCompare(b.name)):[];
function draw(){const h=hits(),n=Math.ceil(h.length/25)||1;if(page>=n)page=n-1;$('#res').innerHTML=`<div class="row"><b>${h.length} record(s)</b><button class="btn ghost" onclick="window.print()">Print</button><button class="btn" onclick="exportM()">Download PDF</button>${h.length?(F.arch?'<button class="btn" onclick="bulkSet(false)">Restore all</button>':'<button class="btn ghost" onclick="bulkSet(true)">Archive all</button>'):''}</div>${F.arch?'<p class="mut"><small>Archived records are hidden from normal lists. Open one, or tap Restore, to bring it back.</small></p>':''}${h.slice(page*25,page*25+25).map(row).join('')||'<p class="mut">No matching records.</p>'}<div class="row"><button class="btn ghost" ${page?'':'disabled'} onclick="page--;draw()">Prev</button><span>${page+1}/${n}</span><button class="btn ghost" ${page<n-1?'':'disabled'} onclick="page++;draw()">Next</button></div>`}
function saveF(){const n=prompt('Name for this filter?');if(!n)return;const s=JSON.parse(localStorage.sf||'{}');s[n]={...F};localStorage.sf=JSON.stringify(s);list()}
async function bulkSet(v){const h=hits();if(!confirm(v?`Archive ${h.length} patient record(s)? They can be restored later.`:`Restore ${h.length} archived record(s)?`))return;try{const t=db.transaction('patients','readwrite');h.forEach(p=>t.objectStore('patients').put({...p,deleted:v,updated:Date.now()}));await new Promise((a,b)=>{t.oncomplete=a;t.onerror=()=>b(t.error)});await log(v?'bulk-archive':'bulk-restore',h.length+' records');await load();toast((v?'Archived ':'Restored ')+h.length);list()}catch(e){toast('Failed: '+e.message,1)}}
/* form */
const fld=(n,l,v,t='text',x='')=>`<label>${l}<input name="${n}" type="${t}" value="${esc(v||'')}" ${x}></label>`;
const sel=(n,l,o,v)=>`<label>${l}<select name="${n}">${o.map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('')}</select></label>`;
const ta=(n,l,v)=>`<label>${l}<textarea name="${n}" rows="2">${esc(v||'')}</textarea></label>`;
function pform(id,pre={}){const p=P.find(x=>x.id===id)||pre;modal(`<h3>${id?'Edit':'Add'} patient</h3><form id="pf" onsubmit="return savePt(event,'${id||''}')">${fld('name','Full name *',p.name,'text','required')}${fld('dob','Date of birth',p.dob,'date')}${sel('gender','Gender',['','Male','Female','Other','Prefer not to say'],p.gender)}${fld('phone','Mobile (10 digits)',p.phone,'tel')}${fld('address','Address',p.address)}${fld('village','Village/City',p.village)}${fld('district','District',p.district)}${fld('state','State',p.state||'Maharashtra')}
${fld('aadhaar','Aadhaar (12 digits)'+(p.aadL?' — leave blank to keep existing':''),'','text','inputmode="numeric" autocomplete="off"')}${fld('abha','ABHA (14 digits)'+(p.abhL?' — leave blank to keep existing':''),'','text','inputmode="numeric" autocomplete="off"')}${sel('blood','Blood group',['','A+','A-','B+','B-','AB+','AB-','O+','O-'],p.blood)}${fld('caste','Caste / category (optional)',p.caste,'text','list="cl" autocomplete="off"')}<datalist id="cl"><option>General</option><option>OBC</option><option>SC</option><option>ST</option><option>NT / VJNT</option><option>SBC</option><option>Other</option><option>Prefer not to say</option></datalist>${ta('allergies','Allergies',p.allergies)}${ta('history','Medical history',p.history)}${fld('diseases','Diagnoses (separate with ;)',(p.diseases||[]).join('; '))}${ta('meds','Current medications',p.meds)}${ta('notes','Notes',p.notes)}${fld('emergency','Emergency contact',p.emergency)}${fld('family','Family ID',p.family)}${sel('relation','Relation in family',['','Father','Mother','Spouse','Son','Daughter','Sibling','Other'],p.relation)}${fld('reg','Registration date',p.reg||today(),'date')}
<label><input type="checkbox" name="consent" style="width:auto" ${p.consent?'checked':''}> Patient has consented to data storage</label><div class="row"><button type="button" class="btn ghost" onclick="closeM()">Cancel</button><button class="btn">Save</button></div></form>`)}
async function savePt(e,id){e.preventDefault();const f=new FormData($('#pf')),o={};for(const[k,v]of f)o[k]=v.trim();o.phone=normPh(o.phone);o.aadhaar=o.aadhaar.replace(/\D/g,'');o.abha=o.abha.replace(/\D/g,'');
const er=!o.name?'Name is required.':o.dob&&!validDate(o.dob)?'Invalid or future date of birth.':o.phone&&!/^[6-9]\d{9}$/.test(o.phone)?'Mobile must be 10 digits.':o.aadhaar&&o.aadhaar.length!==12?'Aadhaar must be 12 digits.':o.abha&&o.abha.length!==14?'ABHA must be 14 digits.':'';if(er)return toast(er,1);
const old=P.find(x=>x.id===id)||{},p={...old,...o,diseases:o.diseases.split(/[;,]/).map(s=>s.trim()).filter(Boolean),consent:!!f.get('consent'),updated:Date.now(),deleted:old.deleted||false};delete p.aadhaar;delete p.abha;
try{if(o.aadhaar){p.aad=await seal(key,o.aadhaar);p.aadL=o.aadhaar.slice(-4)}if(o.abha){p.abh=await seal(key,o.abha);p.abhL=o.abha.slice(-4)}
if(id)await R(st('patients','readwrite').put(p));else{p.id=await nextId();await R(st('patients','readwrite').add(p))}
await log(id?'edit':'add',p.id);await load();closeM();toast('Saved');go(view)}catch(x){toast('Save failed: '+x.message,1)}return false}
/* profile */
function profile(id){const p=P.find(x=>x.id===id);if(!p)return;const fam=p.family?P.filter(x=>x.family===p.family&&x.id!==id&&!x.deleted):[];
modal(`<h3>${esc(p.name)} <small>${p.id}</small>${p.deleted?' <small>(archived)</small>':''}</h3><div class="grid">${[['Age',age(p.dob)],['DOB',p.dob],['Gender',p.gender],['Mobile',p.phone],['Village/City',p.village],['District',p.district],['Blood',p.blood],['Caste / category',p.caste],['Registered',p.reg],['Diagnoses',(p.diseases||[]).join(', ')],['Allergies',p.allergies],['History',p.history],['Medications',p.meds],['Notes',p.notes],['Emergency',p.emergency],['Consent',p.consent?'Yes':'No']].map(([l,v])=>`<div><small>${l}</small><br>${esc(v??'—')||'—'}</div>`).join('')}</div>
<p>Aadhaar: ${p.aadL?'XXXX XXXX '+p.aadL+' <button class="btn ghost" onclick="reveal(\''+id+'\',\'aad\')">Reveal</button>':'—'}<br>ABHA: ${p.abhL?'XXXXXXXXXX'+p.abhL+' <button class="btn ghost" onclick="reveal(\''+id+'\',\'abh\')">Reveal</button>':'—'}</p>
<h4>Family ${esc(p.family||'')}</h4>${fam.map(x=>`<div class="item" onclick="profile('${x.id}')">${esc(x.name)} <small>${esc(x.relation||'')} · ${x.id}</small></div>`).join('')||'<p class="mut">No linked members.</p>'}
<div class="row"><button class="btn" onclick="pform('${id}')">Edit</button><button class="btn ghost" onclick="pform('',{family:'${esc(p.family||'F-'+p.id.slice(1))}',village:'${esc(p.village||'')}',district:'${esc(p.district||'')}',state:'${esc(p.state||'')}',address:'${esc(p.address||'')}'})">Add family member</button><button class="btn ghost" onclick="linkEx('${id}')">Link existing</button>${p.family?`<button class="btn ghost" onclick="unlink('${id}')">Remove from family</button>`:''}
<button class="btn ghost" onclick="window.print()">Print</button>${p.deleted?`<button class="btn" onclick="setDel('${id}',false)">Restore</button>`:`<button class="btn ghost" onclick="setDel('${id}',true)">Archive</button>`}<button class="btn red" onclick="delPerm('${id}')">Delete permanently</button><button class="btn ghost" onclick="closeM()">Close</button></div>`)}
async function reveal(id,f){const pw=await ask('Re-enter your PIN to reveal');if(pw==null)return;if(!await verifyPin(pw)){toast('Incorrect PIN',1);return profile(id)}const p=P.find(x=>x.id===id);await log('reveal',id+' '+f);modal(`<h3>${f==='aad'?'Aadhaar':'ABHA'}</h3><p style="font-size:22px">${esc(await unseal(key,p[f]))}</p><button class="btn" onclick="profile('${id}')">Back</button>`)}
async function upd(id,ch,a){const p=P.find(x=>x.id===id);try{await R(st('patients','readwrite').put({...p,...ch,updated:Date.now()}));await log(a,id);await load();toast('Done');return true}catch(e){toast('Failed: '+e.message,1)}}
async function setDel(id,v){if(!confirm(v?'Archive this record? It can be restored later.':'Restore this record?'))return;if(await upd(id,{deleted:v},v?'archive':'restore')){closeM();go(view)}}
async function delPerm(id){const q=P.find(x=>x.id===id);if(!confirm(`PERMANENTLY delete ${q?q.name:'this record'} (${id})? This cannot be undone. Tip: Archive keeps it recoverable.`))return;try{await R(st('patients','readwrite').delete(id));await log('delete',id);await load();closeM();toast('Deleted');go(view)}catch(e){toast('Failed: '+e.message,1)}}
async function unlink(id){if(confirm('Remove from family? The patient record is kept.')){await upd(id,{family:'',relation:''},'unlink');profile(id)}}
async function linkEx(id){const o=await ask('Patient ID to link (e.g. P000012)',false);if(!o)return;const q=P.find(x=>x.id===o.trim().toUpperCase());if(!q)return toast('Patient not found',1);const rel=await ask('Relationship of that person (Father, Mother, Spouse, Son, Daughter, Sibling, Other)',false);const p=P.find(x=>x.id===id),fid=p.family||'F-'+id.slice(1);if(!p.family)await upd(id,{family:fid},'link');await upd(q.id,{family:fid,relation:rel||''},'link');profile(id)}
/* import */
function csv(t){const r=[];let w=[],f='',q=0;for(let i=0;i<t.length;i++){const c=t[i];if(q){if(c=='"'){if(t[i+1]=='"'){f+='"';i++}else q=0}else f+=c}else if(c=='"')q=1;else if(c==','){w.push(f);f=''}else if(c=='\n'||c=='\r'){if(c=='\r'&&t[i+1]=='\n')i++;w.push(f);f='';if(w.some(x=>x.trim()))r.push(w);w=[]}else f+=c}w.push(f);if(w.some(x=>x.trim()))r.push(w);return r}
const toCsv=rows=>rows.map(r=>r.map(v=>{v=String(v??'');if(/^[=+\-@]/.test(v))v="'"+v;return/[",\n\r]/.test(v)?'"'+v.replace(/"/g,'""')+'"':v}).join(',')).join('\r\n');
function imp(){IM=null;$('#main').innerHTML=`<div class="card"><h3>Import patients (CSV)</h3><p class="mut">Processed on this phone only. Excel users: File → Save As → CSV. Existing records are never overwritten.</p><input type="file" accept=".csv,text/csv" onchange="pickF(this.files[0])"><button class="btn ghost" onclick="save('sample_patients.csv',new Blob([toCsv([COLS.map(c=>c[1]),['','Sample Name','1980-05-20','Female','9876500000','Village','Pune','Maharashtra','O+','Diabetes;Hypertension','F-1','Mother','2025-01-01']])],{type:'text/csv'}))">Download template</button></div><div id="imp"></div>`}
async function pickF(f){if(!f)return;const t=(await f.text()).replace(/^\uFEFF/,''),r=csv(t);if(r.length<2)return toast('File has no data rows',1);IM={h:r[0],rows:r.slice(1),map:{},dup:'skip'};IM.h.forEach((h,i)=>{const c=COLS.find(c=>c[1].toLowerCase()===h.trim().toLowerCase()||c[0]===h.trim().toLowerCase());if(c)IM.map[c[0]]=i});impUI()}
function recOf(r){const g=k=>IM.map[k]==null?'':(r[IM.map[k]]||'').trim(),o={};COLS.forEach(([k])=>o[k]=g(k));o.dob=normDate(o.dob);o.phone=normPh(o.phone);o.reg=normDate(o.reg)||today();return o}
function analyze(){const keys=new Set(P.map(p=>(p.name+p.dob+p.phone).toLowerCase())),ids=new Set(P.map(p=>p.id)),seen=new Set(),res={ok:[],bad:[],dup:[]};
IM.rows.forEach((r,i)=>{const o=recOf(r),k=(o.name+o.dob+o.phone).toLowerCase(),er=!o.name?'missing name':o.dob&&!validDate(o.dob)?'bad date of birth':o.phone&&!/^[6-9]\d{9}$/.test(o.phone)?'bad mobile':'';if(er)return res.bad.push([i+2,er]);if(keys.has(k)||seen.has(k)||(o.id&&ids.has(o.id)))return res.dup.push([i+2,o]);seen.add(k);res.ok.push(o)});IM.res=res;return res}
function impUI(){const a=analyze();$('#imp').innerHTML=`<div class="card"><h4>Map columns</h4><div class="grid">${COLS.map(([k,l])=>`<div><label>${l}<select onchange="IM.map['${k}']=this.value===''?null:+this.value;impUI()"><option value="">— skip —</option>${IM.h.map((h,i)=>`<option value="${i}" ${IM.map[k]===i?'selected':''}>${esc(h)}</option>`).join('')}</select></label></div>`).join('')}</div></div>
<div class="card"><h4>Preview</h4><p>✅ ${a.ok.length} valid · ⚠️ ${a.dup.length} duplicates · ❌ ${a.bad.length} invalid</p>${a.ok.slice(0,5).map(o=>`<div><b>${esc(o.name)}</b> <small>${esc(o.dob)} ${esc(o.phone)} ${esc(o.diseases)}</small></div>`).join('')}${a.bad.length?`<details><summary>Errors</summary>${a.bad.slice(0,50).map(([r,e])=>`<div>Row ${r}: ${e}</div>`).join('')}</details>`:''}
<label>Duplicates<select onchange="IM.dup=this.value;impUI()"><option value="skip">Skip duplicates</option><option value="add" ${IM.dup==='add'?'selected':''}>Import duplicates as new records</option></select></label><button class="btn" id="go" onclick="runImp()">Import ${a.ok.length+(IM.dup==='add'?a.dup.length:0)} records</button><progress id="pg" value="0" max="1" hidden style="width:100%"></progress></div>`}
async function runImp(){if(!confirm('Start import?'))return;const a=IM.res,list=[...a.ok,...(IM.dup==='add'?a.dup.map(d=>({...d[1],id:''})):[])],pg=$('#pg');pg.hidden=false;pg.max=list.length;$('#go').disabled=true;let done=0,fail=0;
try{for(let i=0;i<list.length;i+=500){const ch=list.slice(i,i+500);let seq=(await mget('seq'))||0;const t=db.transaction(['patients','meta'],'readwrite'),ps=t.objectStore('patients');
ch.forEach(o=>{const id=o.id||('P'+String(++seq).padStart(6,'0'));ps.put({...o,id,diseases:o.diseases.split(/[;,]/).map(s=>s.trim()).filter(Boolean),deleted:false,consent:false,updated:Date.now()})});t.objectStore('meta').put(seq,'seq');
await new Promise((x,y)=>{t.oncomplete=x;t.onerror=()=>y(t.error);t.onabort=()=>y(t.error)});done+=ch.length;pg.value=done;await sleep(0)}}catch(e){fail=list.length-done;toast('Import stopped: '+e.message,1)}
await log('import',`${done} imported, ${a.dup.length} duplicates, ${a.bad.length} invalid, ${fail} failed`);await load();$('#imp').innerHTML=`<div class="card"><h3>Import summary</h3><p>Imported: ${done}<br>Duplicates found: ${a.dup.length} (${IM.dup==='add'?'imported':'skipped'})<br>Invalid rows: ${a.bad.length}<br>Failed: ${fail}</p><button class="btn" onclick="go('list')">View patients</button></div>`}
/* export / backup */
async function save(name,blob){if(window.self!==window.top&&blob.type==='application/pdf'){modal(`<h3>Downloads are blocked in this preview</h3><p class="mut">Nothing was saved. The installed app saves the PDF as a real file. Here, use the Print button and choose “Save as PDF”.</p><button class="btn" onclick="closeM()">Close</button>`);return false}if(window.self!==window.top){const t=await blob.text();modal(`<h3>Downloads are blocked in this preview</h3><p class="mut">Nothing was saved. Copy the text below into a file named <b>${esc(name)}</b>. The installed app saves real files.</p><textarea id="cp" rows="8" readonly>${esc(t)}</textarea><div class="row"><button class="btn" onclick="cpy()">Copy</button><button class="btn ghost" onclick="closeM()">Close</button></div>`);return false}const f=new File([blob],name,{type:blob.type});if(navigator.canShare?.({files:[f]})){try{await navigator.share({files:[f],title:name});return true}catch(e){if(e.name==='AbortError')return false}}const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),9e3);return true}
function exportM(f){const h=hits();modal(`<h3>Download ${h.length} record(s) as PDF</h3><p class="mut">Aadhaar and ABHA are never exported.</p><div class="grid">${COLS.map(([k,l])=>`<label><input type="checkbox" style="width:auto" value="${k}" ${['id','name','gender','phone','village','diseases','family'].includes(k)||k==='dob'?'checked':''}> ${l}</label>`).join('')}</div><div class="row"><button class="btn ghost" onclick="closeM()">Cancel</button><button class="btn" onclick="doExp()">Download PDF</button></div>`)}
async function doExp(){const cs=[...document.querySelectorAll('#modal input:checked')].map(x=>x.value);if(!cs.length)return toast('Select columns',1);const pw=await ask('Re-enter PIN to confirm export');if(pw==null)return;if(!await verifyPin(pw))return toast('Incorrect PIN',1);const h=hits(),hd=cs.map(k=>COLS.find(c=>c[0]===k)[1]);
return pdfOut(hd,h.map(p=>cs.map(k=>String(k==='diseases'?(p.diseases||[]).join('; '):p[k]??''))));}
async function backup(){const pw=await ask('Choose a backup passphrase (needed to restore)');if(!pw||pw.length<8)return pw!=null&&toast('Use at least 8 characters',1);try{const ps=[];for(const p of P){const q={...p};if(p.aad)q.aadX=await unseal(key,p.aad);if(p.abh)q.abhX=await unseal(key,p.abh);delete q.aad;delete q.abh;ps.push(q)}
const salt=crypto.getRandomValues(new Uint8Array(16)),k=await derive(pw,salt),s=await seal(k,JSON.stringify({v:1,t:Date.now(),patients:ps,audit:await R(st('audit').getAll())}));
if(await save('medicare_backup_'+today()+'.mcb',new Blob([JSON.stringify({v:1,salt:b64(salt),...s})],{type:'application/octet-stream'}))){await mset('lastBackup',Date.now());await log('backup',ps.length+' records');toast('Backup file created ('+ps.length+' records)');more()}}catch(e){toast('Backup FAILED: '+e.message,1)}}
async function restore(f){if(!f)return;const pw=await ask('Backup passphrase');if(!pw)return;try{const o=JSON.parse(await f.text()),d=JSON.parse(await unseal(await derive(pw,ub64(o.salt)),o));if(!Array.isArray(d.patients)||d.patients.some(p=>!p.id||!p.name))throw new Error('invalid structure');
const have=new Set(P.map(p=>p.id)),nw=d.patients.filter(p=>!have.has(p.id));if(!confirm(`Backup contains ${d.patients.length} records: ${nw.length} new, ${d.patients.length-nw.length} already exist and will be left unchanged. Add the new ones?`))return;
const rs=[];for(const p of nw){const q={...p};if(q.aadX){q.aad=await seal(key,q.aadX)}if(q.abhX){q.abh=await seal(key,q.abhX)}delete q.aadX;delete q.abhX;rs.push(q)}const t=db.transaction('patients','readwrite');rs.forEach(q=>t.objectStore('patients').add(q));
await new Promise((x,y)=>{t.oncomplete=x;t.onerror=()=>y(t.error)});await log('restore',nw.length+' added');await load();toast('Restored '+nw.length+' records');more()}catch(e){toast('Restore failed (wrong passphrase or damaged file)',1)}}
/* more */
async function audit(){const a=(await R(st('audit').getAll())).reverse().slice(0,200);modal(`<h3>Audit log</h3>${a.map(x=>`<div><small>${new Date(x.t).toLocaleString()}</small> ${esc(x.a)} ${esc(x.d)}</div>`).join('')}<button class="btn" onclick="closeM()">Close</button>`)}
async function demo(){if(!confirm('Add 20 FICTIONAL demo patients?'))return;const F1=['Asha','Ravi','Meera','Sunil','Kavita'],L=['Demo-Patil','Demo-Joshi','Demo-More','Demo-Shinde'],D=['Diabetes','Hypertension','Asthma','Thyroid','Fever','Arthritis'];
let s=(await mget('seq'))||0;const t=db.transaction(['patients','meta'],'readwrite');for(let i=0;i<20;i++){const y=1940+Math.floor(Math.random()*75),id='P'+String(++s).padStart(6,'0');t.objectStore('patients').put({id,name:F1[i%5]+' '+L[i%4],dob:`${y}-0${1+i%9}-1${i%9}`,gender:i%5==1||i%5==3?'Male':'Female',phone:'98765'+String(10000+i),village:['Demoville','Sampletown'][i%2],district:'Pune',state:'Maharashtra',diseases:[D[i%6],...(i%3?[]:[D[(i+2)%6]])],family:'F-D'+(i%4),relation:'Other',reg:today(),demo:true,deleted:false,updated:Date.now()})}t.objectStore('meta').put(s,'seq');await new Promise(x=>t.oncomplete=x);await load();toast('Demo data added');home()}
async function more(){const lb=await mget('lastBackup'),_i=setTimeout(instStatus,0),od=lb&&(Date.now()-lb)/864e5>7||!lb;$('#main').innerHTML=`<div class="card"><h3>Settings &amp; security</h3><div class="row"><button class="btn" onclick="chgPin()">Change PIN / password</button><button class="btn ghost" onclick="newRecovery()">New recovery code</button><button class="btn ghost" onclick="lock()">Lock now</button></div></div><div class="card"><h3>Archived records</h3><p>${P.filter(p=>p.deleted).length} archived record(s)</p><button class="btn" onclick="openArchive()">Open archive</button></div><div class="card"><h3>Backup &amp; restore</h3><p>${lb?'Last backup: '+new Date(lb).toLocaleString():'No backup made yet.'} ${od&&A().length?'<b style="color:#c0392b">⚠ Backup recommended</b>':''}</p><button class="btn" onclick="backup()">Create encrypted backup</button><label class="btn ghost" style="display:inline-block">Restore backup<input type="file" hidden onchange="restore(this.files[0])"></label><button class="btn ghost" onclick="pasteRestore()">Paste backup text</button><p class="mut"><small>Move the .mcb file to another phone via USB/WhatsApp/email; it is AES-encrypted and useless without the passphrase. If you lose the passphrase or the device PIN, data cannot be recovered.</small></p></div>
<div class="card"><h3>Tools</h3><div class="row"><button class="btn ghost" onclick="audit()">Audit log</button><button class="btn ghost" onclick="dq()">Data-quality report</button><button class="btn ghost" onclick="demo()">Add demo data</button><button class="btn ghost" onclick="localStorage.t=localStorage.t?'':'dark';document.documentElement.dataset.t=localStorage.t">Light/Dark</button><button class="btn" onclick="lock()">Lock now</button></div></div>
<div class="card"><h3>Install & offline use</h3><div id="ins"></div></div><div class="card"><h3>Privacy</h3><p class="mut"><small>App version ${VER}</small></p><p class="mut"><small>All data stays on this device. No analytics, ads or cloud. Caste/category is sensitive: record it only if needed and with the patient's consent (it is not in exports unless you tick it). Aadhaar/ABHA are encrypted with your PIN-derived key; other fields are stored unencrypted in the browser database (protect the phone with a screen lock). Verify current Indian legal requirements (e.g. DPDP Act) before production use.</small></p></div>`}
function dq(){const a=A(),c=(f,l)=>`<div>${l}: <b>${a.filter(f).length}</b></div>`;modal(`<h3>Data-quality report</h3>${c(p=>!p.dob,'Missing date of birth')}${c(p=>!p.phone,'Missing mobile')}${c(p=>!p.gender,'Missing gender')}${c(p=>!(p.diseases||[]).length,'Missing diagnosis')}${c(p=>!p.consent,'No consent recorded')}<button class="btn" onclick="closeM()">Close</button>`)}

function cpy(){const t=$('#cp');t.select();(navigator.clipboard?navigator.clipboard.writeText(t.value):Promise.reject()).then(()=>toast('Copied'),()=>{document.execCommand('copy');toast('Copied')})}
async function pasteRestore(){const t=await ask('Paste the backup text',false);if(t)restore({text:async()=>t})}
