function one(x){if(x.nodeType===3){const s=x.nodeValue.trim();if(MR[s])x.nodeValue=x.nodeValue.replace(s,MR[s])}else if(x.nodeType===1){if(x.tagName==='OPTION'&&!x.hasAttribute('value'))x.setAttribute('value',x.textContent);const ph=x.getAttribute('placeholder');if(ph&&MR[ph])x.setAttribute('placeholder',MR[ph])}}
function tr(n){if(localStorage.lg!=='mr')return;one(n);if(n.nodeType!==1)return;const w=document.createTreeWalker(n,5);let x;while(x=w.nextNode())one(x)}
new MutationObserver(m=>{const s=new Set();m.forEach(r=>r.addedNodes.forEach(n=>s.add(n)));s.forEach(n=>n.isConnected&&tr(n))}).observe(document.body,{childList:true,subtree:true});
function navL(){document.querySelectorAll('nav button').forEach(b=>{const n=b.lastChild;if(!b.dataset.en)b.dataset.en=n.nodeValue.trim();n.nodeValue=localStorage.lg==='mr'?MR[b.dataset.en]:b.dataset.en})}
async function setLg(){localStorage.lg=localStorage.lg==='mr'?'':'mr';navL();closeM();if(!$('#app').hidden)go(view);else lockUI(!await mget('auth'))}

async function mkPdf(jp,w,h){const parts=[],off=[];let len=0;const push=b=>{if(typeof b==='string')b=te.encode(b);parts.push(b);len+=b.length},obj=(n,s)=>{off[n]=len;push(n+' 0 obj\n'+s+'\nendobj\n')},N=jp.length;
push('%PDF-1.4\n');obj(1,'<</Type/Catalog/Pages 2 0 R>>');obj(2,`<</Type/Pages/Count ${N}/Kids [${jp.map((_,i)=>(3+3*i)+' 0 R').join(' ')}]>>`);
jp.forEach((b,i)=>{const cs='q 595 0 0 842 0 0 cm /Im0 Do Q';obj(3+3*i,`<</Type/Page/Parent 2 0 R/MediaBox [0 0 595 842]/Resources<</XObject<</Im0 ${5+3*i} 0 R>>>>/Contents ${4+3*i} 0 R>>`);obj(4+3*i,`<</Length ${cs.length}>>\nstream\n${cs}\nendstream`);off[5+3*i]=len;push(`${5+3*i} 0 obj\n<</Type/XObject/Subtype/Image/Width ${w}/Height ${h}/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length ${b.length}>>\nstream\n`);push(b);push('\nendstream\nendobj\n')});
const c=3+3*N,x=len;let t=`xref\n0 ${c}\n0000000000 65535 f \n`;for(let n=1;n<c;n++)t+=String(off[n]).padStart(10,'0')+' 00000 n \n';push(t+`trailer\n<</Size ${c}/Root 1 0 R>>\nstartxref\n${x}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}

const lat=s=>{const u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i)&255;return u};
const wts=(hd,rows)=>{const w=hd.map((h,i)=>Math.min(40,Math.max(5,h.length,...rows.slice(0,500).map(r=>String(r[i]).length))));const t=w.reduce((a,b)=>a+b,0);return w.map(x=>x/t)};
async function textPdf(hd,rows,title){const land=hd.length>6,PW=land?842:595,PH=land?595:842,M=30,lh=12,bot=36,y0=PH-62-lh,per=Math.floor((y0-bot)/lh)+1,np=Math.ceil(rows.length/per),W=wts(hd,rows).map(x=>x*(PW-2*M)),X=[];let a=M;W.forEach(w=>{X.push(a);a+=w});
const E=s=>String(s).replace(/[\r\n\t]+/g,' ').replace(/[\\()]/g,'\\$&'),cut=(s,w)=>{s=E(s);const n=Math.max(2,Math.floor((w-6)/4.3));return s.length>n?s.slice(0,n-1)+'.':s};
const parts=[],off=[];let len=0;const push=b=>{if(typeof b==='string')b=lat(b);parts.push(b);len+=b.length},obj=(n,s)=>{off[n]=len;push(n+' 0 obj\n'+s+'\nendobj\n')};
push('%PDF-1.4\n');obj(1,'<</Type/Catalog/Pages 2 0 R>>');obj(2,`<</Type/Pages/Count ${np}/Kids [${[...Array(np)].map((_,i)=>(5+2*i)+' 0 R').join(' ')}]>>`);obj(3,'<</Type/Font/Subtype/Type1/BaseFont/Helvetica/Encoding/WinAnsiEncoding>>');obj(4,'<</Type/Font/Subtype/Type1/BaseFont/Helvetica-Bold/Encoding/WinAnsiEncoding>>');
for(let i=0;i<np;i++){const rs=rows.slice(i*per,i*per+per);let c=`BT /F2 12 Tf 0.04 0.15 0.27 rg 1 0 0 1 ${M} ${PH-30} Tm (${E(title)}) Tj ET\nBT /F1 8 Tf 0.35 g 1 0 0 1 ${M} ${PH-44} Tm (${new Date().toLocaleDateString('en-GB')}  -  ${rows.length} records) Tj ET\n0.06 0.62 0.6 rg ${M} ${PH-62-3} ${PW-2*M} 14 re f\nBT /F2 8 Tf 1 g\n`;
hd.forEach((h,k)=>c+=`1 0 0 1 ${(X[k]+3).toFixed(1)} ${PH-62} Tm (${cut(h,W[k])}) Tj\n`);c+='ET\n';
rs.forEach((r,n)=>{const y=y0-n*lh;if(n%2)c+=`0.93 0.97 0.97 rg ${M} ${y-3} ${PW-2*M} ${lh} re f\n`;c+='BT /F1 8 Tf 0 g\n';r.forEach((v,k)=>c+=`1 0 0 1 ${(X[k]+3).toFixed(1)} ${y} Tm (${cut(v,W[k])}) Tj\n`);c+='ET\n'});
c+=`BT /F1 7 Tf 0.5 g 1 0 0 1 ${M} 20 Tm (Confidential - contains patient information. Aadhaar/ABHA not included.   Page ${i+1}/${np}) Tj ET\n`;
obj(5+2*i,`<</Type/Page/Parent 2 0 R/MediaBox [0 0 ${PW} ${PH}]/Resources<</Font<</F1 3 0 R/F2 4 0 R>>>>/Contents ${6+2*i} 0 R>>`);const b=lat(c);off[6+2*i]=len;push(`${6+2*i} 0 obj\n<</Length ${b.length}>>\nstream\n`);push(b);push('\nendstream\nendobj\n');if(i%20===19){toast('Creating PDF… '+Math.round(i/np*100)+'%');await sleep(0)}}
const n=5+2*np,x=len;let t=`xref\n0 ${n}\n0000000000 65535 f \n`;for(let k=1;k<n;k++)t+=String(off[k]).padStart(10,'0')+' 00000 n \n';push(t+`trailer\n<</Size ${n}/Root 1 0 R>>\nstartxref\n${x}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
async function imgPdf(hd,rows,title){const W=1190,H=1684,c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d'),ws=wts(hd,rows).map(v=>v*1070),per=31,np=Math.ceil(rows.length/per),jp=[];
const fit=(t,w)=>{t=String(t??'');x.font=x.font;if(x.measureText(t).width<=w)return t;while(t.length>1&&x.measureText(t+'…').width>w)t=t.slice(0,-1);return t+'…'};
for(let pi=0;pi<np;pi++){x.fillStyle='#fff';x.fillRect(0,0,W,H);x.fillStyle='#0b2545';x.font='bold 34px sans-serif';x.fillText(title,60,80);x.font='20px sans-serif';x.fillStyle='#555';x.fillText(`${new Date().toLocaleDateString()}  ·  ${rows.length}  ·  ${pi+1}/${np}`,60,115);
let y=170;x.fillStyle='#0f9d9a';x.fillRect(60,y-30,1070,44);x.fillStyle='#fff';x.font='bold 20px sans-serif';let cx=70;hd.forEach((h,k)=>{x.fillText(fit(h,ws[k]-12),cx,y);cx+=ws[k]});y+=44;
rows.slice(pi*per,pi*per+per).forEach((r,i)=>{if(i%2){x.fillStyle='#eef6f6';x.fillRect(60,y-30,1070,44)}x.fillStyle='#111';x.font='20px sans-serif';cx=70;r.forEach((v,k)=>{x.fillText(fit(v,ws[k]-12),cx,y);cx+=ws[k]});y+=44});
x.fillStyle='#888';x.font='16px sans-serif';x.fillText('Confidential — contains patient information. Aadhaar/ABHA not included.',60,1650);
jp.push(new Uint8Array(await(await new Promise(r=>c.toBlob(r,'image/jpeg',.85))).arrayBuffer()));if(pi%5===4){toast('Creating PDF… '+Math.round(pi/np*100)+'%');await sleep(0)}}
return mkPdf(jp,W,H)}
async function pdfOut(hd,rows){if(!rows.length)return toast('No records to export',1);const L=s=>localStorage.lg==='mr'&&MR[s]||s,hl=hd.map(L),title='MediCare Patient Manager - '+L('Patients'),nl=/[^\u0000-\u00ff]/;toast('Creating PDF…');await sleep(50);
try{let blob;if(!hl.some(v=>nl.test(v))&&!rows.some(r=>r.some(v=>nl.test(v))))blob=await textPdf(hl,rows,title);else{if(rows.length>1500&&!confirm(`This list has Marathi/non-English text, so pages are saved as images: about ${Math.ceil(rows.length/31)} pages and a large file. Continue?`))return;blob=await imgPdf(hl,rows,'MediCare Patient Manager — '+L('Patients'))}
if(await save('patients_'+today()+'.pdf',blob)){await log('export-pdf',rows.length+' rows');toast('PDF created ('+(blob.size/1048576).toFixed(1)+' MB)')}}catch(e){toast('PDF failed: '+e.message,1)}}

let dip;addEventListener('beforeinstallprompt',e=>{e.preventDefault();dip=e;instStatus()});addEventListener('appinstalled',()=>{dip=null;toast('App installed');instStatus()});
function netB(){$('#mr').textContent=navigator.onLine?'● Online':'● Offline'}addEventListener('online',netB);addEventListener('offline',netB);netB();
async function instStatus(){const e=$('#ins');if(!e)return;const sa=matchMedia('(display-mode: standalone)').matches||navigator.standalone,fr=window.self!==window.top;let sw='no';if('serviceWorker'in navigator&&!fr){const r=await navigator.serviceWorker.getRegistration().catch(()=>null);sw=r&&r.active?(navigator.serviceWorker.controller?'yes':'reload'):'no'}
e.innerHTML=`<div>${fr?'Preview mode: install and offline use are not available here.':sa?'✅ Installed on this phone':'Not installed yet'}</div>${fr?'':`<div>${sw==='yes'?'✅ Ready to work offline (no internet needed)':sw==='reload'?'Almost ready: close and reopen the app once':'Offline files not saved yet — open once with internet'}</div>`}${dip&&!sa&&!fr?'<button class="btn" onclick="doInst()">Install app on this phone</button>':''}<p class="mut"><small>Android: open in Chrome, tap ⋮ → “Install app” or “Add to Home screen”. After the first load, the app works fully offline. All patient data stays on this phone.</small></p>`}
async function doInst(){if(!dip)return;dip.prompt();await dip.userChoice;dip=null;instStatus()}
navL();boot();
